<script>
(function(){
  "use strict";

  // ---------- shared coin-rendering engine ----------

  const PALETTES = {
    platinum: {base:'#d7dbe0', light:'#ffffff', dark:'#3f444a', accent:'#a7adb3', rim:'#202327'},
    bronze:   {base:'#b06a2e', light:'#ffd9a0', dark:'#4a2a10', accent:'#7a431c', rim:'#2c1808'},
    silver:   {base:'#c7ccd1', light:'#ffffff', dark:'#4d5155', accent:'#9aa0a5', rim:'#26292c'},
    gold:     {base:'#d8b23a', light:'#fff3bf', dark:'#5c4310', accent:'#a67e1c', rim:'#2e2107'},
    black:    {base:'#33333a', light:'#9a9aad', dark:'#050507', accent:'#1d1d22', rim:'#000000'}
  };

  function roundRectPath(ctx,x,y,w,h,r){
    const rr = Math.max(0.001, Math.min(r, Math.abs(w)/2, Math.abs(h)/2));
    ctx.beginPath();
    ctx.moveTo(x+rr,y);
    ctx.arcTo(x+w,y,x+w,y+h,rr);
    ctx.arcTo(x+w,y+h,x,y+h,rr);
    ctx.arcTo(x,y+h,x,y,rr);
    ctx.arcTo(x,y,x+w,y,rr);
    ctx.closePath();
  }

  function drawArcText(ctx, text, radius, R, centerAngle, inward, color){
    ctx.save();
    ctx.fillStyle = color;
    ctx.font = `bold ${Math.max(1,Math.round(R*0.095))}px Georgia, 'Times New Roman', serif`;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    const chars = text.split('');
    const widths = chars.map(c => ctx.measureText(c).width + R*0.012);
    const total = widths.reduce((a,b)=>a+b,0);
    const totalAngle = total / radius;
    let a = centerAngle - totalAngle/2;
    for(let i=0;i<chars.length;i++){
      const w = widths[i];
      const charAngle = w / radius;
      const mid = a + charAngle/2;
      ctx.save();
      ctx.rotate(mid + Math.PI/2);
      ctx.translate(0, -radius);
      if(inward) ctx.rotate(Math.PI);
      ctx.fillText(chars[i], 0, 0);
      ctx.restore();
      a += charAngle;
    }
    ctx.restore();
  }

  function drawLaurel(ctx,R,color){
    ctx.save();
    ctx.strokeStyle = color;
    for(const side of [-1,1]){
      for(let i=0;i<7;i++){
        const angle = Math.PI/2 + side*(0.18 + i*0.11);
        const r1 = R*0.5, r2 = R*0.68;
        ctx.lineWidth = R*0.018;
        ctx.beginPath();
        ctx.moveTo(Math.cos(angle)*r1, Math.sin(angle)*r1);
        ctx.lineTo(Math.cos(angle)*r2, Math.sin(angle)*r2);
        ctx.stroke();
      }
    }
    ctx.restore();
  }

  function drawFaceContent(ctx, R, palette, mode, denomText, angle){
    ctx.save();
    ctx.beginPath();
    ctx.arc(0,0,R,0,Math.PI*2);
    ctx.clip();

    // base metallic gradient
    const grad = ctx.createRadialGradient(-R*0.35,-R*0.4,R*0.05, 0,0,R*1.15);
    grad.addColorStop(0, palette.light);
    grad.addColorStop(0.45, palette.base);
    grad.addColorStop(1, palette.dark);
    ctx.fillStyle = grad;
    ctx.fillRect(-R,-R,2*R,2*R);

    // engine-turned rings texture
    ctx.lineWidth = Math.max(1,R*0.006);
    for(let r=R*0.2; r<R*0.97; r+=R*0.055){
      ctx.beginPath();
      ctx.arc(0,0,r,0,Math.PI*2);
      ctx.strokeStyle = 'rgba(255,255,255,0.06)';
      ctx.stroke();
    }

    // raised rim
    ctx.lineWidth = R*0.09;
    ctx.strokeStyle = palette.dark;
    ctx.beginPath(); ctx.arc(0,0,R*0.93,0,Math.PI*2); ctx.stroke();
    ctx.lineWidth = R*0.025;
    ctx.strokeStyle = palette.light;
    ctx.beginPath(); ctx.arc(0,0,R*0.885,0,Math.PI*2); ctx.stroke();

    if(mode === 'front'){
      drawArcText(ctx,'WASTEDTOKEN MINT', R*0.78, R, -Math.PI/2, false, palette.dark);
      drawArcText(ctx,'CHALLENGE COIN SERIES', R*0.78, R, Math.PI/2, true, palette.dark);

      ctx.save();
      ctx.font = `bold ${Math.round(R*0.95)}px Georgia, 'Times New Roman', serif`;
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillStyle = palette.dark;
      ctx.fillText('W', R*0.025, R*0.025);
      ctx.fillStyle = palette.light;
      ctx.fillText('W', -R*0.02, -R*0.02);
      ctx.fillStyle = palette.base;
      ctx.fillText('W', 0, 0);
      ctx.restore();

      for(let i=0;i<8;i++){
        const a = (i/8)*Math.PI*2;
        const x = Math.cos(a)*R*0.62, y = Math.sin(a)*R*0.62;
        ctx.beginPath();
        ctx.arc(x,y,R*0.02,0,Math.PI*2);
        ctx.fillStyle = palette.dark;
        ctx.fill();
      }
    } else {
      drawArcText(ctx,'WASTEDTOKEN MINT', R*0.78, R, -Math.PI/2, false, palette.dark);
      drawArcText(ctx,'FINE ALLOY EDITION', R*0.78, R, Math.PI/2, true, palette.dark);

      ctx.save();
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.font = `bold ${Math.round(R*0.32)}px Georgia, 'Times New Roman', serif`;
      ctx.fillStyle = palette.dark;
      ctx.fillText(denomText, R*0.02, -R*0.05 + R*0.02);
      ctx.fillStyle = palette.light;
      ctx.fillText(denomText, -R*0.02, -R*0.05 - R*0.02);
      ctx.fillStyle = palette.base;
      ctx.fillText(denomText, 0, -R*0.05);

      ctx.font = `bold ${Math.round(R*0.14)}px Georgia, 'Times New Roman', serif`;
      ctx.fillStyle = palette.dark;
      ctx.fillText('TOKENS', R*0.02, R*0.24 + R*0.02);
      ctx.fillStyle = palette.light;
      ctx.fillText('TOKENS', -R*0.02, R*0.24 - R*0.02);
      ctx.fillStyle = palette.base;
      ctx.fillText('TOKENS', 0, R*0.24);
      ctx.restore();

      drawLaurel(ctx, R, palette.dark);
    }

    // specular highlight that rakes across the surface as angle changes
    const hx = Math.sin(angle*2) * R*0.55;
    const hy = Math.cos(angle*3) * R*0.22 - R*0.12;
    ctx.save();
    ctx.translate(hx,hy);
    ctx.scale(1,0.4);
    const hg = ctx.createRadialGradient(0,0,0, 0,0,R*0.55);
    hg.addColorStop(0,'rgba(255,255,255,0.85)');
    hg.addColorStop(0.4,'rgba(255,255,255,0.25)');
    hg.addColorStop(1,'rgba(255,255,255,0)');
    ctx.fillStyle = hg;
    ctx.globalCompositeOperation = 'lighter';
    ctx.beginPath();
    ctx.arc(0,0,R*0.55,0,Math.PI*2);
    ctx.fill();
    ctx.restore();

    ctx.restore(); // end clip
  }

  function drawEdge(ctx, halfW, R, palette){
    const h = R*1.94;
    ctx.save();
    roundRectPath(ctx, -halfW, -h/2, halfW*2, h, Math.min(halfW,10));
    ctx.fillStyle = palette.rim;
    ctx.fill();

    ctx.save();
    roundRectPath(ctx, -halfW, -h/2, halfW*2, h, Math.min(halfW,10));
    ctx.clip();
    const step = Math.max(R*0.025, 2.5);
    for(let x=-halfW; x<halfW; x+=step){
      const idx = Math.floor((x+halfW)/step);
      ctx.fillStyle = (idx % 2 === 0) ? palette.dark : palette.accent;
      ctx.fillRect(x, -h/2, step*0.55, h);
    }
    const eg = ctx.createLinearGradient(-halfW,0,halfW,0);
    eg.addColorStop(0,'rgba(255,255,255,0.25)');
    eg.addColorStop(0.5,'rgba(0,0,0,0.18)');
    eg.addColorStop(1,'rgba(255,255,255,0.12)');
    ctx.fillStyle = eg;
    ctx.fillRect(-halfW,-h/2,halfW*2,h);
    ctx.restore();

    ctx.restore();
  }

  function renderCoin(ctx, R, angle, tilt, palette, denomText){
    const scaleX = Math.cos(angle);
    const rx = Math.max(Math.abs(scaleX), 0.035) * R;
    const mode = scaleX >= 0 ? 'front' : 'back';
    const edgeHalfW = (1 - Math.abs(scaleX)) * R*0.34 + R*0.045;

    ctx.save();
    ctx.rotate(tilt);

    drawEdge(ctx, edgeHalfW, R, palette);

    ctx.save();
    ctx.scale(Math.max(rx/R, 0.001), 1);
    drawFaceContent(ctx, R, palette, mode, denomText, angle);
    ctx.restore();

    ctx.restore();
  }

  function drawBackdrop(ctx,w,h){
    const g = ctx.createRadialGradient(w/2,h*0.42,w*0.05, w/2,h*0.5,w*0.65);
    g.addColorStop(0,'#1b1d24');
    g.addColorStop(1,'#0a0b0e');
    ctx.fillStyle = g;
    ctx.fillRect(0,0,w,h);
    ctx.strokeStyle = 'rgba(216,178,58,0.08)';
    ctx.lineWidth = 1;
    ctx.beginPath();
    ctx.arc(w/2,h/2,Math.min(w,h)*0.4,0,Math.PI*2);
    ctx.stroke();
  }

  // ---------- hero coin (graded) ----------

  const hcanvas = document.getElementById('coin-hero');
  const hctx = hcanvas.getContext('2d');

  function drawHero(t){
    const w = hcanvas.width, h = hcanvas.height;
    hctx.clearRect(0,0,w,h);
    drawBackdrop(hctx,w,h);

    const cx = w/2, cy = h/2;
    const R = Math.min(w,h) * 0.32;
    const angle = t * Math.PI * 2;
    const tilt = Math.sin(angle*2) * 0.16;

    hctx.save();
    hctx.translate(cx, cy + R*0.02);

    // contact shadow
    hctx.save();
    hctx.translate(0, R*1.05);
    hctx.scale(1, 0.22);
    const sg = hctx.createRadialGradient(0,0,0, 0,0,R*1.05);
    sg.addColorStop(0,'rgba(0,0,0,0.45)');
    sg.addColorStop(1,'rgba(0,0,0,0)');
    hctx.fillStyle = sg;
    hctx.beginPath();
    hctx.arc(0,0,R*1.05,0,Math.PI*2);
    hctx.fill();
    hctx.restore();

    renderCoin(hctx, R, angle, tilt, PALETTES.platinum, '10,000');

    hctx.restore();
  }

  let playing = true;
  let rafId = null;
  let startTime = null;
  const PERIOD_MS = 4200;

  function loop(ts){
    if(!playing) return;
    if(startTime === null) startTime = ts;
    const t = ((ts - startTime) % PERIOD_MS) / PERIOD_MS;
    drawHero(t);
    rafId = requestAnimationFrame(loop);
  }

  drawHero(0);
  rafId = requestAnimationFrame(loop);

  window.demo = {
    canvas: hcanvas,
    setTime(t){
      const tt = ((t % 1) + 1) % 1;
      drawHero(tt);
    },
    pause(){
      playing = false;
      if(rafId !== null){
        cancelAnimationFrame(rafId);
        rafId = null;
      }
    }
  };

  // ---------- collection tiles (decorative, independently animated) ----------

  const EDITIONS = [
    {selector:'[data-edition="bronze"] .edition-canvas', material:'bronze', denom:'2,500', phase:0.0},
    {selector:'[data-edition="silver"] .edition-canvas', material:'silver', denom:'5,000', phase:1.6},
    {selector:'[data-edition="gold"] .edition-canvas',   material:'gold',   denom:'1,000', phase:3.1},
    {selector:'[data-edition="black"] .edition-canvas',  material:'black',  denom:'250',   phase:4.7}
  ];

  EDITIONS.forEach(cfg => {
    const canvas = document.querySelector(cfg.selector);
    if(!canvas) return;
    const ctx = canvas.getContext('2d');
    let t0 = null;

    function frame(ts){
      if(t0 === null) t0 = ts;
      const angle = ((ts - t0) / 7000) * Math.PI*2 + cfg.phase;
      const tilt = Math.sin(angle*2) * 0.1;
      const w = canvas.width, h = canvas.height;

      ctx.clearRect(0,0,w,h);
      drawBackdrop(ctx,w,h);

      const R = Math.min(w,h) * 0.34;
      ctx.save();
      ctx.translate(w/2, h/2);
      renderCoin(ctx, R, angle, tilt, PALETTES[cfg.material], cfg.denom);
      ctx.restore();

      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);
  });

})();
